<script lang="ts">let{message,tone='success',onClose}:{message:string;tone?:'success'|'danger';onClose:()=>void}=$props();$effect(()=>{const timer=setTimeout(onClose,3500);return()=>clearTimeout(timer)});</script>
<div class="toast {tone}" role="status"><span>{tone==='success'?'✓':'!'}</span><p>{message}</p><button aria-label="Fechar" onclick={onClose}>×</button></div>
<style>.toast{position:fixed;z-index:100;right:var(--space-6);bottom:var(--space-6);display:grid;min-width:18rem;max-width:25rem;grid-template-columns:auto 1fr auto;align-items:center;gap:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-md);background:var(--surface-card);padding:var(--space-4);box-shadow:var(--shadow-md);font-size:var(--text-sm)}.toast>span{display:grid;width:1.5rem;height:1.5rem;place-items:center;border-radius:50%;font-weight:800}.success>span{background:var(--status-success-bg);color:var(--status-success)}.danger>span{background:var(--status-danger-bg);color:var(--status-danger)}button{border:0;background:transparent;color:var(--text-tertiary);font-size:1.2rem;cursor:pointer}@media(max-width:500px){.toast{right:var(--space-4);bottom:var(--space-4);left:var(--space-4);min-width:0}}</style>
